# -*- coding: utf-8 -*- 
import os 
T["templates/dashboard.html"] = "{% raw %}{% extends 'base.html' %}{% block content %}<h1>Dashboard</h1><div class='stats'><div class='stat-box'><h3>Total orders</h3><div class='value'>{{ stats.total_orders or 0 }}</div></div><div class='stat-box'><h3>Delivered</h3><div class='value' style='color:#27ae60'>{{ stats.delivered or 0 }}</div></div><div class='stat-box'><h3>Revenue</h3><div class='value'>{{ '%.0f'|format(stats.revenue or 0) }} RUB</div></div></div><div class='card'><h3>Top products</h3><table><thead><tr><th>Product</th><th>Qty</th><th>Revenue</th></tr></thead><tbody>{% for p in top_products %}<tr><td>{{ p.product_name }}</td><td>{{ p.qty }}</td><td>{{ '%.0f'|format(p.revenue) }} RUB</td></tr>{% endfor %}</tbody></table></div>{% endblock %}{% endraw %}" 
